+		t.Fatal(err)
+	}
+	if res.Cursor != "sess-1" {
+		t.Fatalf("cursor %q", res.Cursor)
+	}
+	if len(res.Events) != 0 {
+		t.Fatalf("claude host keeps Cursor only, events %+v", res.Events)
+	}
+}

